'use strict';
/**
 * FE mock server data contributor for the entity set BusinessProcess (draft root: process with steps and variants).
 * Every saved change of the process model creates a new process version.
 * Behavior in mock-backend/services/ProcessService.js; initial data: BusinessProcess.json (generated by the seed).
 */
const processService = require('../../../../mock-backend/services/ProcessService');
const traceability = require('../../../../mock-backend/services/TraceabilityService');
const { addMessages, run } = require('../../../../mock-backend/services/mockServerAdapter');
const { SEVERITY, sapMessage } = require('../../../../mock-backend/common/messages');
const { CURRENT_USER } = require('../../../../mock-backend/services/TestCaseService');

module.exports = {
    async onBeforeAddEntry(keys, data) {
        Object.assign(data, processService.initialBusinessProcess(data));
    },

    /** Prepare (Save, step 1): consistency of steps and variants */
    async onDraftPrepare(actionDefinition, responseData, keys, odataRequest) {
        await run(this, odataRequest, (repo) => processService.validateBusinessProcess(repo, keys.ProcessID), { boundAction: true });
    },

    /** Activate: new process version when the model changed; derived fields, value helps, read models */
    async onAfterAction(actionDefinition, actionData, keys, responseData, odataRequest) {
        const response = await responseData;
        if (actionDefinition.name === 'Activate' && keys?.ProcessID) {
            await run(this, odataRequest, async (repo) => {
                const { versioned, version } = await processService.onProcessActivated(repo, keys.ProcessID, CURRENT_USER);
                await traceability.refreshAll(repo);
                if (versioned && version > 1) {
                    addMessages(odataRequest, [
                        sapMessage(913, `Process ${keys.ProcessID} saved as version ${version}. Test cases refer to the version they were designed for.`, {
                            severity: SEVERITY.SUCCESS
                        })
                    ]);
                }
            });
        }
        return response;
    }
};
